using System;using System.Linq;using System.Drawing;using System.Windows.Forms;namespace ServiceTool{internal static class CompactWindowsTests{static System.Collections.Generic.IEnumerable<Control> Walk(Control p){foreach(Control c in p.Controls){yield return c;foreach(var x in Walk(c))yield return x;}}[STAThread]static int Main(){try{int n=0;foreach(bool dark in new[]{false,true})foreach(var f in new ManagerModuleForm[]{new WindowsFeaturesForm(true),new ToolsDeploymentForm(true)})using(f){f.SetTheme(dark,false);f.Show();for(int i=0;i<8;i++)Application.DoEvents();if(Walk(f).OfType<ThemeToggleButton>().Any(t=>t.Visible))throw new Exception("Theme visible");n++;using(var b=new Bitmap(f.Width,f.Height)){f.DrawToBitmap(b,new Rectangle(Point.Empty,b.Size));b.Save(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory,f.GetType().Name+"-"+dark+".png"));}}Console.WriteLine("PASS: "+n+" compact window/theme checks; snapshots saved; preview only.");return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}}}